package com.webapp.auth;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import java.io.IOException;
import java.util.Base64;
import java.security.SecureRandom;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.logging.Logger;

@WebServlet("/api/session")
public class SessionTokenHandler extends HttpServlet {
    private static final Logger log = Logger.getLogger(SessionTokenHandler.class.getName());
    private static final byte[] MASTER_KEY = System.getenv("SESSION_KEY").getBytes(StandardCharsets.UTF_8);
    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final int IV_LENGTH = 16;
    private static final int HMAC_LENGTH = 32;

    // Token format: base64(IV || ciphertext || HMAC)
    // Plaintext format: "role=<role>;user=<username>;exp=<timestamp>"

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String token = req.getHeader("X-Session-Token");
        if (token == null || token.isEmpty()) {
            resp.sendError(401, "Missing session token");
            return;
        }

        TokenValidationResult result = validateAndDecrypt(token);
        if (!result.isValid()) {
            resp.sendError(result.getHttpStatus(), result.getMessage());
            return;
        }

        String role = extractField(result.getPlaintext(), "role");
        String user = extractField(result.getPlaintext(), "user");

        if ("admin".equals(role)) {
            resp.getWriter().write("{\"access\": \"full\", \"user\": \"" + user + "\"}");
        } else if ("user".equals(role)) {
            resp.getWriter().write("{\"access\": \"limited\", \"user\": \"" + user + "\"}");
        } else {
            resp.sendError(403, "Unknown role");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String role = authenticateUser(username, req.getParameter("password"));
        if (role == null) {
            resp.sendError(401, "Invalid credentials");
            return;
        }

        long expiry = System.currentTimeMillis() + 3600000;
        String plaintext = "role=" + role + ";user=" + username + ";exp=" + expiry;
        String token = encrypt(plaintext);
        resp.setHeader("X-Session-Token", token);
        resp.getWriter().write("{\"status\": \"authenticated\"}");
    }

    private TokenValidationResult validateAndDecrypt(String tokenB64) {
        try {
            byte[] tokenBytes = Base64.getDecoder().decode(tokenB64);
            if (tokenBytes.length < IV_LENGTH + 16 + HMAC_LENGTH) {
                return TokenValidationResult.error(401, "Malformed token");
            }

            byte[] iv = Arrays.copyOfRange(tokenBytes, 0, IV_LENGTH);
            byte[] ciphertext = Arrays.copyOfRange(tokenBytes, IV_LENGTH, tokenBytes.length - HMAC_LENGTH);
            byte[] providedHmac = Arrays.copyOfRange(tokenBytes, tokenBytes.length - HMAC_LENGTH, tokenBytes.length);

            // Verify HMAC first for integrity
            byte[] computedHmac = computeHmac(iv, ciphertext);
            if (!constantTimeEquals(computedHmac, providedHmac)) {
                return TokenValidationResult.error(401, "Invalid token");
            }

            // HMAC verified, now decrypt
            byte[] plainBytes = decryptPayload(iv, ciphertext);
            if (plainBytes == null) {
                return TokenValidationResult.error(401, "Invalid token");
            }

            String plaintext = new String(plainBytes, StandardCharsets.UTF_8);

            // Check expiry
            String expStr = extractField(plaintext, "exp");
            if (expStr == null || Long.parseLong(expStr) < System.currentTimeMillis()) {
                return TokenValidationResult.error(401, "Token expired");
            }

            return TokenValidationResult.success(plaintext);
        } catch (Exception e) {
            log.warning("Token validation failed: " + e.getClass().getSimpleName());
            return TokenValidationResult.error(401, "Invalid token");
        }
    }

    private byte[] decryptPayload(byte[] iv, byte[] ciphertext) {
        try {
            SecretKeySpec keySpec = new SecretKeySpec(MASTER_KEY, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(iv);
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
            return cipher.doFinal(ciphertext);
        } catch (javax.crypto.BadPaddingException e) {
            return null;
        } catch (Exception e) {
            return null;
        }
    }

    private String encrypt(String plaintext) {
        try {
            byte[] iv = new byte[IV_LENGTH];
            new SecureRandom().nextBytes(iv);
            SecretKeySpec keySpec = new SecretKeySpec(MASTER_KEY, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(iv);
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);
            byte[] ciphertext = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));
            byte[] hmac = computeHmac(iv, ciphertext);
            byte[] token = new byte[iv.length + ciphertext.length + hmac.length];
            System.arraycopy(iv, 0, token, 0, iv.length);
            System.arraycopy(ciphertext, 0, token, iv.length, ciphertext.length);
            System.arraycopy(hmac, 0, token, iv.length + ciphertext.length, hmac.length);
            return Base64.getEncoder().encodeToString(token);
        } catch (Exception e) {
            throw new RuntimeException("Encryption failed", e);
        }
    }

    private byte[] computeHmac(byte[] iv, byte[] ciphertext) {
        try {
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            // Derive HMAC key from master key (simplified - production would use HKDF)
            SecretKeySpec hmacKey = new SecretKeySpec(
                Arrays.copyOf(MASTER_KEY, 32), "HmacSHA256");
            mac.init(hmacKey);
            mac.update(iv);
            return mac.doFinal(ciphertext);
        } catch (Exception e) {
            throw new RuntimeException("HMAC computation failed", e);
        }
    }

    private boolean constantTimeEquals(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }

    private String extractField(String data, String field) {
        for (String part : data.split(";")) {
            if (part.startsWith(field + "=")) {
                return part.substring(field.length() + 1);
            }
        }
        return null;
    }

    private String authenticateUser(String username, String password) {
        // Stub - would check against secure credential store
        if ("admin".equals(username) && "s3cur3P@ss!".equals(password)) return "admin";
        if (username != null && password != null && password.length() >= 8) return "user";
        return null;
    }
}

class TokenValidationResult {
    private final boolean valid;
    private final String plaintext;
    private final int httpStatus;
    private final String message;

    private TokenValidationResult(boolean valid, String plaintext, int httpStatus, String message) {
        this.valid = valid;
        this.plaintext = plaintext;
        this.httpStatus = httpStatus;
        this.message = message;
    }

    static TokenValidationResult success(String plaintext) {
        return new TokenValidationResult(true, plaintext, 200, "OK");
    }

    static TokenValidationResult error(int status, String message) {
        return new TokenValidationResult(false, null, status, message);
    }

    boolean isValid() { return valid; }
    String getPlaintext() { return plaintext; }
    int getHttpStatus() { return httpStatus; }
    String getMessage() { return message; }
}
